result:
.questionSubmit{
  // height: 100%;
  height: 180vh;
  display: flex;
  overflow-y: auto;
  .left{
    width: 919px;
    height: 100%;
    box-shadow: 0 4px 25px 0 #e9f0ff;
    background: #fff;
    padding: 15px;
    .left_top{
      display: flex;
      justify-content: space-between;
      align-items: center;
      margin-bottom: 20px;
      .question_tabs{
        display: flex;
        color: #999;
        .question_tabs_item{
          margin-right: 40px;
          cursor: pointer;
          font-size: 14px;
          display: flex;
          justify-content: center;
          align-items: center;
          padding: 8px;
          &.is_active{
            color: #1061ff;
            background: #eaf4ff;
            border-radius: 4px;
          }
        }
      }
      .question_search{
        overflow: hidden;
        display: flex;
        align-items: center;
        ::v-deep .el-input__inner{
          background-color: #fff;
          border-radius: 30px;
          // border: 1px solid #1061ff;
          border: 1px solid rgba(200,255,255,0.9);
          color: #000;
        }
        ::v-deep .el-input_placeholder{
          color: #000;
        }
        ::v-deep .el-input__icon{
          // color: #1061ff;
          color: #007bff;
        }
        .search_btn{
          white-space: nowrap;
          background-image: url('../img/questionsearch.png');
          background-size: 100% 100%;
          height: 40px;
          line-height: 40px;
          text-align: center;
          color: #fff;
          padding: 0 20px;
          margin-left: 20px;
          cursor: pointer;
        }
      }
    }
    .left_content{
      height: calc(100% - 107px);
      overflow-y: auto;
      .question_list_item{
        margin-bottom: 20px;
        padding-right: 10px;
        padding-bottom: 20px;
        border-bottom: 2px solid #f0f0f0;
        .item_top{
          width: 100%;
          margin-bottom: 8px;
          display: flex;
          align-items: center;
          .item_status{
            font-size: 11px;
            color: #fff;

            display: inline-block;
            padding: 1px 5px;
            border-radius: 2px;
            margin-right: 10px;
            white-space: nowrap;
          }
          .item_status.item_status0{
            background: #ffb800;
          }
          .item_status.item_status1{
            background: #00c868;
          }
          .item_status.item_status2{
            background: #c4c4c4;
          }
          .item_status.item_status21{
            background: rgb(230,162,60);
          }
          .item_status.item_status3{
            background: #c4c4c4;
          }
          .item_title{
            font-size: 16px;
            color: #000;
            font-weight: bold;
            line-height: 22px;
            white-space: nowrap;
            overflow: hidden;
            text-overflow: ellipsis;
            margin-right: 20px;
            font-family: '黑体';
            cursor: pointer;
            &:hover{
              color: #1061ff;
            }
          }
          .item_time{
            line-height: 22px;
            flex: 1;
            text-align: right;
            white-space: nowrap;
            font-size: 14px;
          }

        }
        .item_middle{
          background-color: #ecf5ff;
          padding: 10px;
          border-radius: 3px;
          font-size: 14px;
          margin-bottom: 8px;
        }
        .item_footer{
          display: flex;
          justify-content: space-between;
          font-size: 14px;
          color: #333;
          img{vertical-align: bottom; margin-right: 7px;}
        }
      }
    }
  }
  .right{
    flex: 1;
    padding-left: 35px;
    .btn_box{
      display: flex;
      align-items: center;
      justify-content: center;
      height: 61px;
      width: 100%;
      border-radius: 10px;
      font-size: 22px;
      line-height: 61px;
      text-align: center;
      cursor: pointer;
      img{margin-right: 30px}

    }
    .submit_question_btn{
      background-image: url('../img/submitbtnback.png');
      background-size: 100% 100%;
      color: #fff;
      margin-bottom: 25px;
    }
    .my_btn{
      border: 1px solid rgba(76,137,255,1);
    }

    .tatols{
        border: 1px solid #4c89ff;
        border-radius: 10px;
        margin-top: 25px;
        padding: 15px 20px;
        .line{
          line-height: 30px;
        }
    }
  }
}
::-webkit-scrollbar{
  width: 5px;
  height: 5px;
}
::v-deep ::-webkit-scrollbar-button{
  display: none
}
::-webkit-scrollbar-thumb{
  background: #bed4ff;
  border-radius: 3px
}
::-webkit-scrollbar-track{
  margin: 5px
}
